 15→// ── Robust prompt template substitution ─────────────────────
 16→function applyPromptTemplate(template: string, vars: Record<string, string>): string {
 17→  return template.replace(/\$\{(\w+(?:\.\w+)*)\}/g, (match, key) => {
 18→    if (key in vars) return vars[key];
 19→    console.warn(`Prompt template: unresolved variable ${match}`);
 20→    return "None specified";
 21→  });
