 71→const synonymToCanonical = new Map<string, string>();
 72→for (const [canonical, synonyms] of Object.entries(SKILL_SYNONYMS)) {
 73→  synonymToCanonical.set(canonical, canonical);
 74→  for (const syn of synonyms) synonymToCanonical.set(syn, canonical);
 75→}
 76→
 77→function normalizeSkill(skill: string): string {
 78→  const lower = skill.toLowerCase().trim().replace(/[.\-\/]/g, '').replace(/\s+/g, ' ');
 79→  return synonymToCanonical.get(lower) || synonymToCanonical.get(skill.toLowerCase().trim()) || lower;
 80→}
 81→
 82→function tokenize(term: string): string[] {
 83→  return term.toLowerCase().replace(/[^a-z0-9\s+#]/g, ' ').split(/\s+/).filter(t => t.length > 1);
 84→}
 85→
 86→function tokenOverlap(a: string, b: string): number {
 87→  const tokensA = tokenize(a);
 88→  const tokensB = tokenize(b);
 89→  if (tokensA.length === 0 || tokensB.length === 0) return 0;
 90→  const setB = new Set(tokensB);
 91→  const matched = tokensA.filter(t => setB.has(t)).length;
 92→  return matched / Math.max(tokensA.length, tokensB.length);
 93→}
 94→
 95→function fuzzyMatch(jdTerm: string, resumeTerms: string[]): boolean {
 96→  const normalizedJd = normalizeSkill(jdTerm);
 97→  for (const rt of resumeTerms) {
 98→    const normalizedResume = normalizeSkill(rt);
 99→    if (normalizedJd === normalizedResume) return true;
100→    if (normalizedJd.includes(normalizedResume) || normalizedResume.includes(normalizedJd)) return true;
101→    if (tokenOverlap(normalizedJd, normalizedResume) >= 0.5) return true;
102→  }
103→  return false;
104→}
