192→function parseDate(dateStr: string, currentYear: number, currentMonth: number): number {
193→  if (!dateStr) return 0;
194→  const s = dateStr.trim();
195→
196→  // Try "YYYY-MM" or "MM/YYYY" or "YYYY"
197→  const ymd = s.match(/^(\d{4})[\/\-](\d{1,2})/);
198→  if (ymd) return parseInt(ymd[1]) + (parseInt(ymd[2]) - 1) / 12;
199→
200→  const mdy = s.match(/^(\d{1,2})[\/\-](\d{4})/);
201→  if (mdy) return parseInt(mdy[2]) + (parseInt(mdy[1]) - 1) / 12;
202→
203→  // "Jan 2020", "January 2020"
204→  const monthYear = s.match(/^([a-zA-Z]+)\s+(\d{4})/);
205→  if (monthYear) {
206→    const month = monthNameToNum(monthYear[1]);
207→    if (month > 0) return parseInt(monthYear[2]) + (month - 1) / 12;
208→  }
209→
210→  // Plain year "2020"
211→  const plainYear = s.match(/^(\d{4})$/);
212→  if (plainYear) return parseInt(plainYear[1]);
213→
214→  return 0;
215→}
216→
217→function monthNameToNum(name: string): number {
218→  const months: Record<string, number> = {
219→    jan: 1, january: 1, feb: 2, february: 2, mar: 3, march: 3,
220→    apr: 4, april: 4, may: 5, jun: 6, june: 6,
221→    jul: 7, july: 7, aug: 8, august: 8, sep: 9, september: 9,
222→    oct: 10, october: 10, nov: 11, november: 11, dec: 12, december: 12,
223→  };
224→  return months[name.toLowerCase().trim()] || 0;
225→}
226→
227→function extractRequiredYears(experienceReq: string): number {
228→  if (!experienceReq) return 0;
229→  const match = experienceReq.match(/(\d+)\+?\s*(?:years?|yrs?)/i);
230→  return match ? parseInt(match[1]) : 0;
231→}
232→
233→function scoreExperienceBand(years: number, bands: ExperienceBand[]): number {
234→  for (const band of bands) {
235→    if (years >= band.min_years && years < band.max_years) return band.score;
236→  }
237→  // If beyond all bands, return max score
238→  return bands.length > 0 ? bands[bands.length - 1].score : 50;
239→}
240→
241→function scoreEducation(education: any[], levels: EducationLevel[]): { score: number; highestDegree: string } {
242→  if (!Array.isArray(education) || education.length === 0) {
243→    return { score: 0, highestDegree: "none" };
244→  }
245→
246→  let bestScore = 0;
247→  let bestLevel = "unknown";
248→
249→  for (const edu of education) {
250→    const degree = String(edu.degree || edu.qualification || edu.level || "").toLowerCase().trim();
251→    if (!degree) continue;
252→
253→    for (const level of levels) {
254→      for (const alias of level.aliases) {
255→        if (degree.includes(alias.toLowerCase())) {
256→          if (level.score > bestScore) {
257→            bestScore = level.score;
258→            bestLevel = level.level;
259→          }
260→          break;
261→        }
262→      }
263→    }
264→  }
265→
266→  return { score: bestScore, highestDegree: bestLevel };
267→}
268→
269→function ruleBasedScoreResume(
270→  parsedJson: any,
271→  jdAnalysis: any,
272→  cfg: {
273→    experience_bands: ExperienceBand[];
274→    education_levels: EducationLevel[];
275→    rule_dimension_weights: Record<string, number>;
276→    must_have_penalty_per_missing: number;
277→    hard_fit_cap: number;
278→    algorithm_version: number;
279→  },
280→) {
281→  const p = parsedJson || {};
282→  const allResumeTerms = extractResumeTerms(parsedJson);
283→
284→  // ── Skill Match ──
285→  const jdSkills = [
286→    ...(jdAnalysis.critical_must_haves || []),
287→    ...(jdAnalysis.preferred_must_haves || []),
288→    ...(jdAnalysis.nice_to_have || []),
289→  ];
290→  const matchedSkills: string[] = [];
291→  const missingSkills: string[] = [];
292→  for (const skill of jdSkills) {
293→    if (fuzzyMatch(skill, allResumeTerms)) matchedSkills.push(skill);
294→    else missingSkills.push(skill);
295→  }
296→  const skillScore = jdSkills.length > 0 ? Math.round((matchedSkills.length / jdSkills.length) * 100) : 50;
297→
298→  // ── Tool Match ──
299→  const jdTools = jdAnalysis.tools || [];
300→  const matchedTools: string[] = [];
301→  const missingTools: string[] = [];
302→  for (const tool of jdTools) {
303→    if (fuzzyMatch(tool, allResumeTerms)) matchedTools.push(tool);
304→    else missingTools.push(tool);
305→  }
306→  const toolScore = jdTools.length > 0 ? Math.round((matchedTools.length / jdTools.length) * 100) : 50;
307→
308→  // ── Experience Fit ──
309→  const rolesWithDates = p.roles_with_dates || [];
310→  const totalYears = extractTotalYears(rolesWithDates);
311→  const requiredYears = extractRequiredYears(jdAnalysis.experience_requirements || "");
312→  let experienceScore = scoreExperienceBand(totalYears, cfg.experience_bands);
313→  if (requiredYears > 0 && totalYears >= requiredYears) {
314→    experienceScore = Math.min(100, experienceScore + 10);
315→  }
316→
317→  // ── Education Fit ──
318→  const education = p.education || [];
319→  const eduResult = scoreEducation(education, cfg.education_levels);
320→  const educationScore = eduResult.score;
321→
322→  // ── Must-Have Coverage ──
323→  const criticalMustHaves = jdAnalysis.critical_must_haves || [];
324→  const matchedMustHaves: string[] = [];
325→  const missingMustHaves: string[] = [];
326→  for (const mh of criticalMustHaves) {
327→    if (fuzzyMatch(mh, allResumeTerms)) matchedMustHaves.push(mh);
328→    else missingMustHaves.push(mh);
329→  }
330→  const mustHaveScore = criticalMustHaves.length > 0
331→    ? Math.round((matchedMustHaves.length / criticalMustHaves.length) * 100) : 100;
332→
333→  // ── Overall Score ──
334→  const weights = cfg.rule_dimension_weights;
335→  let overallScore =
336→    skillScore * (weights.skill_match || 0.30) +
337→    experienceScore * (weights.experience_fit || 0.25) +
338→    toolScore * (weights.tool_match || 0.20) +
339→    educationScore * (weights.education_fit || 0.15) +
340→    mustHaveScore * (weights.must_have_coverage || 0.10);
341→
342→  // Apply must-have penalty
343→  overallScore -= missingMustHaves.length * cfg.must_have_penalty_per_missing;
344→  overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
345→
346→  // Hard fit check
347→  const hardFit = missingMustHaves.length === 0;
348→  if (!hardFit) {
349→    overallScore = Math.min(overallScore, cfg.hard_fit_cap);
350→  }
351→
352→  // ── Build strengths & gaps ──
353→  const dimensionScores = [
354→    { name: "Skill Match", score: skillScore },
355→    { name: "Experience", score: experienceScore },
356→    { name: "Tools", score: toolScore },
357→    { name: "Education", score: educationScore },
358→    { name: "Must-Haves", score: mustHaveScore },
359→  ];
360→  dimensionScores.sort((a, b) => b.score - a.score);
361→  const strengths = dimensionScores.filter(d => d.score >= 60).map(d => `${d.name}: ${d.score}%`);
362→  const gaps = dimensionScores.filter(d => d.score < 50).map(d => `${d.name}: ${d.score}%`);
363→
364→  // Add matched skills to strengths
365→  if (matchedMustHaves.length > 0) {
366→    strengths.push(`Matched must-haves: ${matchedMustHaves.join(", ")}`);
367→  }
368→  if (missingMustHaves.length > 0) {
369→    gaps.push(`Missing must-haves: ${missingMustHaves.join(", ")}`);
370→  }
371→
372→  return {
373→    scoring_version: `rule-v1-algo${cfg.algorithm_version}`,
374→    overall_score: overallScore,
375→    hard_fit: hardFit,
376→    confidence: 100,
377→    skill_score: skillScore,
378→    experience_score: experienceScore,
379→    education_score: educationScore,
380→    category_scores_json: {
381→      skill_match: { score: skillScore, matched: matchedSkills, missing: missingSkills },
382→      experience_fit: { score: experienceScore, years_found: totalYears, years_required: requiredYears },
383→      tool_match: { score: toolScore, matched: matchedTools, missing: missingTools },
384→      education_fit: { score: educationScore, highest_degree: eduResult.highestDegree },
385→      must_have_coverage: { score: mustHaveScore, matched: matchedMustHaves, missing: missingMustHaves },
386→    },
387→    matched_must_haves: matchedMustHaves,
388→    missing_must_haves: missingMustHaves,
389→    missing_skills: [...missingMustHaves, ...missingTools],
390→    strengths_json: strengths,
391→    gaps_json: gaps,
392→    interview_questions: [],
393→    explanation_json: {
394→      summary: `Rule-based scoring: ${matchedSkills.length}/${jdSkills.length} skills matched, ${totalYears} years experience (${requiredYears} required), ${eduResult.highestDegree} degree.`,
395→      scoring_mode: "rule_based",
396→      dimension_breakdown: {
397→        skill_match: skillScore,
398→        experience_fit: experienceScore,
399→        tool_match: toolScore,
400→        education_fit: educationScore,
401→        must_have_coverage: mustHaveScore,
402→      },
403→    },
404→  };
405→}
