416→) {
417→  const dimensionInstructions = dimensions.map((d: any) =>
418→    `- "${d.key}" (${d.label}): ${d.description}. Rubric: 0=${d.rubric?.["0"] || "absent"}, 25=${d.rubric?.["25"] || "weak"}, 50=${d.rubric?.["50"] || "moderate"}, 75=${d.rubric?.["75"] || "strong"}, 100=${d.rubric?.["100"] || "perfect with evidence"}`
419→  ).join("\n");
420→
421→  const criticalMustHaves = (jdAnalysis.critical_must_haves || []).join(", ");
422→  const preferredMustHaves = (jdAnalysis.preferred_must_haves || []).join(", ");
423→
424→  const hardcodedDeepPrompt = `You are an expert recruiter performing deep candidate evaluation.
425→
426→CRITICAL SAFETY RULES:
