471→    : `RESUME TEXT:\n${resumeText.slice(0, maxChars)}`;
472→
473→  const controller = new AbortController();
474→  const timeoutId = setTimeout(() => controller.abort(), 60_000);
475→  const response = await fetch("https://api.openai.com/v1/chat/completions", {
476→    method: "POST",
