494→    throw new Error(`OpenAI score error ${response.status}: ${errBody.slice(0, 200)}`);
495→  }
496→
497→  const data = await response.json();
498→  const content = data.choices?.[0]?.message?.content;
499→  if (!content) throw new Error("OpenAI returned empty deep score response");

500→  if (!content) throw new Error("OpenAI returned empty deep score response");
