504→// ── Process a single resume: parse + score ──────────────────
505→async function processResume(
506→  supabase: any,
507→  resumeId: string,
508→  jobId: string,
509→  userId: string,
510→  cfg: any,
511→  deepScoringPrompt: string | null,
