513→  jdAnalysis: any,
514→  dynamicWeights: any,
515→  jdEmbedding: any,
516→  dimensions: any[],
517→) {
518→  // Step 1: Call parse-resume to extract text + structured data
519→  console.log(`Parsing resume ${resumeId}...`);
