528→    }
529→  } catch (err) {
530→    console.error(`parse-resume call failed for ${resumeId}:`, err);
531→    await logSystemError({ function_name: "rank-resumes", error_type: "PARSE_INVOKE", severity: "warning", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
532→  }
533→
534→  // Step 2: Re-fetch resume after parsing
535→  const { data: resume } = await supabase.from("resumes").select("*").eq("id", resumeId).single();
536→  if (!resume) {
537→    console.error(`Resume ${resumeId} not found after parsing`);
538→    return false;
539→  }
540→
541→  const rawText = resume.parsed_text || "";
542→  const parsedJson = resume.parsed_json;
543→
544→  // Step 3: Check if we have enough content to score
545→  const hasUsefulParsedJson = parsedJson && (
546→    (Array.isArray(parsedJson.skills_with_evidence) && parsedJson.skills_with_evidence.length > 0) ||
547→    (Array.isArray(parsedJson.roles_with_dates) && parsedJson.roles_with_dates.length > 0) ||
548→    (Array.isArray(parsedJson.education) && parsedJson.education.length > 0)
549→  );
550→  if (rawText.trim().length < 50 && !hasUsefulParsedJson) {
551→    console.warn(`Resume ${resumeId}: insufficient content after parsing, inserting zero score`);
552→    const summaryMsg = resume.status === "failed"
553→      ? "Could not extract text from this file. It may be image-based or have unsupported formatting. Please re-upload a text-based PDF or DOCX file."
554→      : "Resume content too short to evaluate. Please re-upload a valid PDF/DOCX.";
555→    const resultData = {
556→      resume_id: resumeId, job_id: jobId, scoring_version: "insufficient",
557→      overall_score: 0, hard_fit: false, confidence: 0,
558→      category_scores_json: {}, strengths_json: [], gaps_json: [],
559→      interview_questions: [], explanation_json: { extraction_failed: true },
560→      matched_must_haves: [], missing_must_haves: [], missing_skills: [],
561→      summary: summaryMsg,
562→      skill_score: null, experience_score: null, education_score: null,
563→    };
564→    const { data: existing } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
565→    if (existing) await supabase.from("results").update(resultData as any).eq("id", existing.id);
566→    else await supabase.from("results").insert(resultData as any);
567→    return false;
568→  }
569→
570→  // Step 4: Score — rule-based or GPT
571→  if (cfg.scoring_mode === "rule_based") {
572→    try {
573→      console.log(`Rule-based scoring for resume ${resumeId}...`);
574→      const ruleResult = ruleBasedScoreResume(parsedJson, jdAnalysis, cfg);
575→
576→      // Update candidate name from parsed data if available
577→      const parsedName = parsedJson?.candidate_name || parsedJson?.name;
578→      if (parsedName && parsedName !== "Unknown Candidate") {
579→        await supabase.from("resumes").update({ candidate_name: parsedName, status: "done" }).eq("id", resumeId);
580→      } else {
581→        await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
582→      }
583→
584→      const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
585→      const resultData = { resume_id: resumeId, job_id: jobId, ...ruleResult };
586→
587→      if (existingResult) {
588→        await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
589→      } else {
590→        await supabase.from("results").insert(resultData as any);
591→      }
592→      console.log(`Resume ${resumeId} rule-scored: overall=${ruleResult.overall_score}, hardFit=${ruleResult.hard_fit}`);
593→      return true;
594→    } catch (err) {
595→      console.error(`Rule-based scoring failed for ${resumeId}:`, err);
596→      await logSystemError({ function_name: "rank-resumes", error_type: "RULE_SCORING", severity: "error", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
597→      await supabase.from("resumes").update({ status: "failed" }).eq("id", resumeId);
598→      return false;
599→    }
600→  }
601→
602→  // Step 5: Deep score with OpenAI (GPT mode)
603→  try {
604→    const resumeText = rawText || JSON.stringify(parsedJson || {});
605→    const deepResult = await deepScoreResume(
606→      job.job_description, resumeText, parsedJson,
607→      jdAnalysis, dimensions, cfg, deepScoringPrompt
608→    );
609→
610→    let overallScore = 0;
611→    const categoryScores = deepResult.category_scores || {};
612→
613→    const normalizeKey = (k: string) => k.toLowerCase().replace(/[\s_-]+/g, "_").trim();
614→    const scoreKeyMap = new Map<string, any>();
615→    for (const [k, v] of Object.entries(categoryScores)) {
616→      scoreKeyMap.set(normalizeKey(k), v);
617→    }
618→
619→    for (const dim of dimensions) {
620→      const weight = dynamicWeights[dim.key] ?? 0;
621→      const scoreEntry = categoryScores[dim.key] || scoreKeyMap.get(normalizeKey(dim.key));
622→      overallScore += (scoreEntry?.score ?? 0) * weight;
623→    }
624→
625→    if (overallScore === 0 && Object.keys(categoryScores).length > 0) {
626→      const allScores = Object.values(categoryScores).map((v: any) => v?.score ?? 0).filter((s: number) => s > 0);
627→      if (allScores.length > 0) overallScore = allScores.reduce((a: number, b: number) => a + b, 0) / allScores.length;
628→    }
629→
630→    overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
631→
632→    // All-zero retry
633→    const allZero = Object.values(categoryScores).every((v: any) => (v?.score ?? 0) === 0);
634→    if (allZero && resumeText.length > 200 && (deepResult.confidence ?? 0) === 0) {
635→      console.warn(`Resume ${resumeId}: all scores=0, retrying once...`);
636→      try {
637→        const retryResult = await deepScoreResume(
638→          job.job_description, resumeText, parsedJson,
639→          jdAnalysis, dimensions, cfg, deepScoringPrompt
640→        );
641→        const retryScores = retryResult.category_scores || {};
642→        const retryAllZero = Object.values(retryScores).every((v: any) => (v?.score ?? 0) === 0);
643→        if (!retryAllZero) {
644→          Object.assign(deepResult, retryResult);
645→          Object.assign(categoryScores, retryScores);
646→          overallScore = 0;
647→          const retryKeyMap = new Map<string, any>();
648→          for (const [k, v] of Object.entries(retryScores)) retryKeyMap.set(normalizeKey(k), v);
649→          for (const dim of dimensions) {
650→            const weight = dynamicWeights[dim.key] ?? 0;
651→            const scoreEntry = retryScores[dim.key] || retryKeyMap.get(normalizeKey(dim.key));
652→            overallScore += (scoreEntry?.score ?? 0) * weight;
653→          }
654→          if (overallScore === 0 && Object.keys(retryScores).length > 0) {
655→            const rs = Object.values(retryScores).map((v: any) => v?.score ?? 0).filter((s: number) => s > 0);
656→            if (rs.length > 0) overallScore = rs.reduce((a: number, b: number) => a + b, 0) / rs.length;
657→          }
658→          overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
659→        }
660→      } catch (retryErr) {
661→        console.error(`Retry scoring failed for ${resumeId}:`, retryErr);
662→      }
663→    }
664→
665→    let hardFit = deepResult.hard_fit !== false;
666→    const missingCritical = deepResult.missing_critical_must_haves || [];
667→    const hardFitCap = cfg.hard_fit_cap ?? 49;
668→    if (missingCritical.length > 0) {
669→      hardFit = false;
670→      overallScore = Math.min(overallScore, hardFitCap);
671→    }
672→
673→    // Update name if scoring found a better one
674→    const bestName = resume.candidate_name;
675→    if (deepResult.candidate_name && deepResult.candidate_name !== "Unknown Candidate") {
676→      await supabase.from("resumes").update({ candidate_name: deepResult.candidate_name, status: "done" }).eq("id", resumeId);
677→    } else {
678→      await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
679→    }
680→
681→    const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
682→    const resultData = {
