 17→function isQualityText(text: string): boolean {
 18→  if (!text || text.trim().length < 30) return false;
 19→  const words = text.split(/\s+/).filter(w => /^[a-zA-Z]{2,}$/.test(w));
 20→  const totalWords = text.split(/\s+/).length;
 21→  const wordRatio = words.length / Math.max(totalWords, 1);
 22→
 23→  // Relaxed threshold for longer texts
 24→  if (text.length > 500 && wordRatio > 0.2 && words.length > 15) return true;
 25→
 26→  // Resume keyword check: if text has common resume words, accept it
 27→  if (text.length > 200) {
 28→    const lower = text.toLowerCase();
 29→    const resumeKeywords = ["experience", "education", "skills", "email", "phone", "university",
 30→      "bachelor", "master", "engineer", "developer", "manager", "work", "project", "team"];
 31→    const matched = resumeKeywords.filter(k => lower.includes(k)).length;
 32→    if (matched >= 3) return true;
 33→  }
 34→
 35→  return wordRatio > 0.3 && words.length > 10;
 36→}
