 38→// ── Detect file type from magic bytes ───────────────────────
 39→function detectFileType(filename: string, bytes: Uint8Array): "pdf" | "docx" | "doc" | "rtf" | "txt" | "unknown" {
 40→  if (bytes.length >= 4) {
 41→    if (bytes[0] === 0x25 && bytes[1] === 0x50 && bytes[2] === 0x44 && bytes[3] === 0x46) return "pdf";
 42→    if (bytes[0] === 0x50 && bytes[1] === 0x4B && bytes[2] === 0x03 && bytes[3] === 0x04) return "docx";
 43→    if (bytes[0] === 0x7B && bytes[1] === 0x5C && bytes[2] === 0x72 && bytes[3] === 0x74) return "rtf";
 44→  }
 45→  const ext = filename.toLowerCase().split(".").pop() || "";
 46→  if (ext === "pdf") return "pdf";
 47→  if (ext === "docx" || ext === "doc") return ext as "docx" | "doc";
 48→  if (ext === "rtf") return "rtf";
 49→  if (ext === "txt" || ext === "text" || ext === "md") return "txt";
 50→  return "unknown";
 51→}
