 53→// ── BT/ET PDF text extraction ───────────────────────────────
 54→function extractPdfText(bytes: Uint8Array): string {
 55→  const raw = new TextDecoder("latin1").decode(bytes);
 56→  const textChunks: string[] = [];
 57→  const btEtRegex = /BT\s([\s\S]*?)ET/g;
 58→  let block;
 59→  while ((block = btEtRegex.exec(raw)) !== null) {
 60→    const parenRegex = /\(([^)]*)\)/g;
 61→    let match;
 62→    while ((match = parenRegex.exec(block[1])) !== null) {
 63→      const decoded = match[1]
 64→        .replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t")
 65→        .replace(/\\\\/g, "\\").replace(/\\\(/g, "(").replace(/\\\)/g, ")");
 66→      if (decoded.trim()) textChunks.push(decoded);
 67→    }
 68→    const tjRegex = /\[([^\]]*)\]\s*TJ|(\([^)]*\))\s*Tj/g;
 69→    let tjMatch;
 70→    while ((tjMatch = tjRegex.exec(block[1])) !== null) {
 71→      const content = tjMatch[1] || tjMatch[2] || "";
 72→      const innerParen = /\(([^)]*)\)/g;
 73→      let ip;
 74→      while ((ip = innerParen.exec(content)) !== null) {
 75→        if (ip[1].trim()) textChunks.push(ip[1]);
 76→      }
 77→    }
 78→  }
 79→  return textChunks.join(" ").replace(/\s+/g, " ").trim().slice(0, 15000);
 80→}
 81→
 82→// ── DOCX extraction (lazy mammoth + XML fallback) ───────────
 83→async function extractDocxText(buffer: ArrayBuffer): Promise<string> {
 84→  try {
 85→    const mammoth = (await import("https://esm.sh/mammoth@1.8.0")).default;
 86→    const result = await mammoth.extractRawText({ arrayBuffer: buffer });
 87→    return (result.value || "").trim().slice(0, 15000);
 88→  } catch {
 89→    return extractDocxFallback(new Uint8Array(buffer));
 90→  }
 91→}
 92→
 93→function extractDocxFallback(bytes: Uint8Array): string {
 94→  const raw = new TextDecoder("utf-8", { fatal: false }).decode(bytes);
 95→  const chunks: string[] = [];
 96→  const textRegex = /<w:t[^>]*>([^<]+)<\/w:t>/g;
 97→  let match;
 98→  while ((match = textRegex.exec(raw)) !== null) {
 99→    if (match[1].trim()) chunks.push(match[1]);
100→  }
101→  if (chunks.length > 0) return chunks.join(" ").slice(0, 15000);
102→
103→  const anyTextRegex = />([^<]{3,})</g;
104→  while ((match = anyTextRegex.exec(raw)) !== null) {
105→    const text = match[1].trim();
106→    if (text.length > 3 && /[a-zA-Z]/.test(text) && !text.startsWith("xmlns")) {
107→      chunks.push(text);
108→    }
109→  }
110→  return chunks.join(" ").slice(0, 15000);
111→}
112→
113→// ── RTF extraction ──────────────────────────────────────────
114→function extractRtfText(bytes: Uint8Array): string {
115→  const raw = new TextDecoder("latin1").decode(bytes);
116→  let text = raw
117→    .replace(/\{\\[^{}]*\}/g, "")
118→    .replace(/\\[a-z]+\d*\s?/g, " ")
119→    .replace(/[{}\\]/g, "")
120→    .replace(/\s+/g, " ")
121→    .trim();
122→  return text.slice(0, 15000);
123→}
124→
125→// ── Safe base64 encoding ────────────────────────────────────
126→function uint8ToBase64(bytes: Uint8Array): string {
127→  let binary = "";
128→  for (let i = 0; i < bytes.length; i++) {
129→    binary += String.fromCharCode(bytes[i]);
130→  }
131→  return btoa(binary);
132→}
