346→    await supabase.from("resumes").update({ status: "processing" }).eq("id", resume_id);
347→
348→    let rawText: string | null = null;
349→    let parsedJson: any = null;
350→    let extractionMethod = "unknown";
351→    let extractionFailed = false;
352→
353→    // Download file
354→    if (resume.file_path) {
355→      const { data: fileData } = await supabase.storage.from("resumes").download(resume.file_path);
356→      if (fileData) {
357→        const buffer = await fileData.arrayBuffer();
358→        const bytes = new Uint8Array(buffer);
