360→        console.log(`Resume ${resume_id}: type=${fileType}, size=${bytes.length} bytes`);
361→
362→        // ── Try lightweight extraction first ──
363→        switch (fileType) {
364→          case "pdf": {
365→            // Try BT/ET extraction
366→            const btEtText = extractPdfText(bytes);
367→            if (btEtText.trim().length > 50 && isQualityText(btEtText)) {
368→              rawText = btEtText;
369→              extractionMethod = "bt_et";
370→              console.log(`Resume ${resume_id}: BT/ET good quality (${rawText.length} chars)`);
371→            }
372→
373→            // If lightweight fails, use Gemini (PRIMARY method for PDFs)
374→            if (!rawText || !isQualityText(rawText)) {
375→              console.log(`Resume ${resume_id}: using Gemini for extraction...`);
376→              const geminiResult = await extractWithGemini(bytes, resume_id, "application/pdf");
377→              if (geminiResult) {
378→                rawText = geminiResult.text;
379→                parsedJson = geminiResult.parsed;
380→                extractionMethod = "gemini_ocr";
381→                console.log(`Resume ${resume_id}: Gemini extracted ${rawText.length} chars`);
382→              }
383→            }
384→
385→            if (!rawText || rawText.trim().length < 30) {
386→              extractionFailed = true;
387→              console.error(`All extraction failed for PDF resume ${resume_id}`);
388→            }
389→            break;
390→          }
391→
392→          case "docx": {
393→            rawText = await extractDocxText(buffer);
394→            extractionMethod = "mammoth";
395→            if (!rawText || rawText.trim().length < 20) {
396→              // Try Gemini for DOCX too
397→              const geminiResult = await extractWithGemini(bytes, resume_id,
398→                "application/vnd.openxmlformats-officedocument.wordprocessingml.document");
399→              if (geminiResult) {
400→                rawText = geminiResult.text;
401→                parsedJson = geminiResult.parsed;
402→                extractionMethod = "gemini_docx";
403→              } else {
404→                extractionFailed = true;
405→              }
406→            }
407→            break;
408→          }
409→
410→          case "doc": {
411→            // Binary .doc — go straight to Gemini
412→            const geminiResult = await extractWithGemini(bytes, resume_id, "application/msword");
413→            if (geminiResult) {
414→              rawText = geminiResult.text;
415→              parsedJson = geminiResult.parsed;
416→              extractionMethod = "gemini_doc";
417→            } else {
418→              extractionFailed = true;
419→            }
420→            break;
421→          }
422→
423→          case "rtf": {
424→            rawText = extractRtfText(bytes);
425→            extractionMethod = "rtf_parser";
426→            if (!rawText || rawText.trim().length < 20) extractionFailed = true;
427→            break;
428→          }
429→
430→          case "txt": {
