432→            extractionMethod = "plaintext";
433→            break;
434→          }
435→
436→          default: {
437→            const textAttempt = new TextDecoder("utf-8", { fatal: false }).decode(bytes).slice(0, 15000);
438→            const printableRatio = textAttempt.replace(/[^\x20-\x7E\n\r\t]/g, "").length / textAttempt.length;
439→            if (printableRatio > 0.8 && textAttempt.trim().length > 50) {
440→              rawText = textAttempt;
441→              extractionMethod = "plaintext_fallback";
442→            } else {
443→              const geminiResult = await extractWithGemini(bytes, resume_id, "application/octet-stream");
444→              if (geminiResult) {
445→                rawText = geminiResult.text;
446→                parsedJson = geminiResult.parsed;
447→                extractionMethod = "gemini_unknown";
448→              } else {
449→                extractionFailed = true;
450→              }
451→            }
452→            break;
